import assert from 'node:assert/strict';
import { performance } from 'node:perf_hooks';
import { uniqueTags } from '../src/tags.js';

const mode = process.argv[2];
if (mode === 'existing') {
  for (const [input, expected] of [
    [[], []],
    [['node', 'js', 'node', 'css', 'js'], ['node', 'js', 'css']],
    [['z', 'a', 'z', 'b', 'a', 'c'], ['z', 'a', 'b', 'c']],
    [['', ' ', '', ' ', 'x'], ['', ' ', 'x']],
    [['__proto__', 'constructor', 'toString', '__proto__'], ['__proto__', 'constructor', 'toString']],
  ]) {
    const before = [...input];
    Object.freeze(input);
    assert.deepEqual(uniqueTags(input), expected);
    assert.deepEqual(input, before);
  }
} else if (mode === 'case') {
  for (const [input, expected] of [
    [['JS', 'Node', 'js', 'NODE', 'css'], ['JS', 'Node', 'css']],
    [['js', 'JS', 'node', 'NODE'], ['js', 'node']],
    [['CSS', 'Js', 'css', 'NODE', 'jS', 'node', 'HTML'], ['CSS', 'Js', 'NODE', 'HTML']],
    [['', '', 'A', 'a', ' a', ' A', 'a ', 'A '], ['', 'A', ' a', 'a ']],
    [['__PROTO__', '__proto__', 'Constructor', 'constructor', 'TOSTRING', 'toString'], ['__PROTO__', 'Constructor', 'TOSTRING']],
    [['École', 'éCOLE', 'Ä', 'ä', 'Ω', 'ω'], ['École', 'Ä', 'Ω']],
  ]) {
    Object.freeze(input);
    assert.deepEqual(uniqueTags(input), expected);
  }
  // Many unique keys, varied first spellings, and nonadjacent duplicates.
  const input = [], expected = [];
  for (let i = 0; i < 100000; i++) {
    const tag = (i % 2 ? 'Tag-' : 'tAG-') + i;
    input.push(tag);
    expected.push(tag);
    if (i % 11 === 0) input.push(tag.toLowerCase());
  }
  for (let i = 99999; i >= 0; i--) input.push('TAG-' + i);
  assert.deepEqual(uniqueTags(input), expected);
} else if (mode === 'speed' || mode === 'benchmark') {
  const input = [];
  for (let i = 0; i < 200000; i++) input.push('Tag-' + i);
  for (let i = 199999; i >= 0; i--) input.push('TAG-' + i);
  // Exclude data construction and module loading from the measurement.
  for (let i = 0; i < 3; i++) uniqueTags(input.slice(0, 10000));
  const times = [];
  for (let i = 0; i < 3; i++) {
    const start = performance.now();
    const result = uniqueTags(input);
    times.push(performance.now() - start);
    assert.ok(Array.isArray(result));
    assert.ok(result.length >= 200000 && result.length <= input.length);
  }
  times.sort((a, b) => a - b);
  if (mode === 'speed') assert.ok(times[1] < 750, `400,000 tags took ${times[1]} ms (median)`);
  else console.log(times[1]);
} else {
  throw new Error('Unknown check mode');
}
